// spec: .qa/e2e/specs/tenders-list.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const TECH = 'טכנולוגיה, מוצר, דאטה ומערכות מידע';
const HEALTH = 'בריאות, מדעי החיים וביוטכנולוגיה';
const ALL = 'כל התחומים';

test.describe('Field chips on /tenders — multi-select, in sync with the sidebar (#9a6100)', () => {
  test('Clicking an active chip removes only it; none selected → «כל התחומים» @desktop @prod-safe #9a6100', async ({ page }) => {
    const chip = (name: string) => page.getByRole('button', { name, exact: true });
    const checkbox = (name: string) => page.getByRole('checkbox', { name, exact: true });
    const count = page.getByText(/^\d+ תוצאות$/);
    const checked = page.locator('aside input[type="checkbox"]:checked');

    // Unfiltered count (reference)
    await page.goto('/tenders');
    await expect(chip(ALL)).toHaveAttribute('aria-pressed', 'true');
    const unfiltered = await count.innerText();

    // 1. Open /tenders?fields=technology,health
    await page.goto('/tenders?fields=technology,health');
    await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'true');
    await expect(chip(HEALTH)).toHaveAttribute('aria-pressed', 'true');

    // 2. Click active «בריאות…» → only «טכנולוגיה…» stays
    await chip(HEALTH).click();
    await expect.poll(() => new URL(page.url()).searchParams.get('fields')).toBe('technology');
    await expect(chip(HEALTH)).toHaveAttribute('aria-pressed', 'false');
    await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'true');
    await expect(checkbox(TECH)).toBeChecked();
    await expect(checkbox(HEALTH)).not.toBeChecked();
    await expect(checked).toHaveCount(1);

    // 3. Click active «טכנולוגיה…» → nothing selected, «כל התחומים» active
    await chip(TECH).click();
    await expect.poll(() => new URL(page.url()).searchParams.get('fields') ?? '').toBe('');
    await expect(chip(TECH)).toHaveAttribute('aria-pressed', 'false');
    await expect(chip(ALL)).toHaveAttribute('aria-pressed', 'true');
    await expect(checked).toHaveCount(0);
    await expect(count).toHaveText(unfiltered);
  });
});
